#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    int T;    cin >> T;     while(T--){        int n;        string s;                cin >> n;        cin >> s;                vector<int>prefix(n) , suffix(n);                set<char>st;                for(int i = 0 ; i < n ; i ++){            st.insert(s[i]);            prefix[i] = st.size();        }                st.clear();                for(int i = n - 1 ; i >= 0 ; i --){            st.insert(s[i]);            suffix[i] = st.size();        }                int ans = 0;                for(int i = 0 ; i < n - 1; i ++){            ans = max(ans , prefix[i] + suffix[i + 1]);        }                cout << ans << endl;    }}